(* UCodeShK.v -- the CODE CATALOG of the user program [shk].
   AUTO-GENERATED by tools/gen_ucode.py.  DO NOT EDIT BY HAND.

   Regenerate the whole layer with `make gen-ucode`; `make check-ucode`
   regenerates and then FAILS if anything moved.  This file alone is

     tools/gen_ucode.py --module Sh --prog shk --spec \
         tools/ucode_shk.txt --out iris/UCodeShK.v

   and WHICH instructions it covers is that spec file's to say. Edit the
   SPEC, never this output: a hand edit here is reverted, silently, by the
   next regeneration, and `make check-ucode` is what notices. Anything the
   generator cannot produce -- a predicate about the program's WRITABLE
   data half, say -- belongs in a hand-written file beside this one, not in
   it.

   The verified-user tier (claude-notes/projects/user-verified.md) drives
   one step from one [uinstr] fact (UmodeMem.v): the pure statement that at
   a given user pc the program's bytes sit in the process image [M], the
   pc's page is mapped fetch-executable, and the fetched word decodes to a
   named AST on any U-mode machine. This file proves those facts for the
   616 instruction(s) of this catalog, from the dumped image
   [User.ShInstrs.sh_bytes].

   Two premises carry every [uinstr] lemma:

     [shk_text_sub M]   -- [M] contains the dumped text (so a proof may talk
                          about a process image that ALSO has rodata, bss, a
                          stack page and an argument area in it);
     [shk_text_layout pt]
                       -- the pure page-table fact: each of the 2 page(s) of
                          the executable segment (0x0 .. 0x1fff) is mapped with a
                          leaf that permits instruction FETCH and a user data
                          LOAD.  The load half is not decoration: a program's
                          .rodata shares a text page and its string literals are
                          handed to [write]/[exec] as buffers.  The DATA page and
                          the heap are NOT this file's business -- they are
                          read-WRITE, and they, the stack and the argument area
                          belong to the program's own hand-written files
                          (UShk*.v / UkShk*.v), which is also where a predicate
                          over the writable half goes -- [UInitArgv.v] is the
                          worked example.

   Image geometry, as dumped:
     text  0x0 .. 0x1264   (4708 bytes)
     PT_LOAD 0x0      filesz 0x1c74   memsz 0x1c74   flags 5   (executable: 2 text page(s))
     PT_LOAD 0x2000   filesz 0x10     memsz 0x98     flags 6
     data  0x1264 .. 0x2010   (2592 bytes)
     entry 0x9ac, MemBase 0x0, MemEnd 0x2098

   Catalogued: 616 instruction(s), 411 distinct word(s), in 22 function(s):
     <start>          0x9ac    .. 0x9b8        6 instr
     <main>           0x8be    .. 0x9a8       77 instr
     <getcmd>         0x0      .. 0x48        29 instr
     <memset>         0xa38    .. 0xa5c       16 instr
     <gets>           0xa86    .. 0xafa       50 instr
     <open>           0xca2    .. 0xca8        3 instr
     <close>          0xc8a    .. 0xc90        3 instr
     <exit>           0xc62    .. 0xc64        2 instr
     <write>          0xc82    .. 0xc88        3 instr
     <read>           0xc7a    .. 0xc80        3 instr
     <runcmd>         0x8e     .. 0x1ce      102 instr
     <fork1>          0x68     .. 0x8a        14 instr
     <fork>           0xc5a    .. 0xc60        3 instr
     <exec>           0xc9a    .. 0xca0        3 instr
     <pipe>           0xc72    .. 0xc78        3 instr
     <wait>           0xc6a    .. 0xc70        3 instr
     <dup>            0xcda    .. 0xce0        3 instr
     <chdir>          0xcd2    .. 0xcd8        3 instr
     <panic>          0x4a     .. 0x64        11 instr
     <fprintf>        0x108e   .. 0x10b6      17 instr
     <vprintf>        0xdce    .. 0x108c     250 instr
     <putc>           0xd12    .. 0xd2e       12 instr

   NOT catalogued, because no proof ever fetches it:
       0xc68 -- exit's [c.jr ra] -- the ecall at 0xc64 never returns
       printint -- arms, and sh's only conversion is %s
       atoi, backcmd, cmdalloc, execcmd, free, fstat, getpid, gettoken, kill,
       link, listcmd, malloc, memcmp, memcpy, memmove, mkdir, mknod,
       nulterminate, parseblock, parsecmd, parseexec, parseline, parsepipe,
       parseredirs, pause, peek, pipecmd, redircmd, sbrk, sbrklazy, seccomp,
       stat, strchr, strcmp, strcpy, strlen, sync, sys_sbrk, unlink, uptime --
       catalog grows to meet them
       printf -- unreachable: every diagnostic in sh.c is an [fprintf(2, ...)]

   SH LANE STAGES 1-2, 5 and the DIAGNOSTIC SUBTREE. THE DIAGNOSTIC SUBTREE
   (ask 7) adds [panic], [fprintf], [vprintf] and [putc] -- the cone every
   one of sh's three fprintf-and-die tails runs through. It is no longer
   cut: iris/UkShDiag.v walks it and discharges UkShRun.v's
   [ush_diag_leaf]. [printf] stays out because sh never calls it (every
   diagnostic in sh.c is an [fprintf(2, ...)]), and [printint] stays out
   because the only formats sh prints are '%s\n', 'exec %s failed\n' and
   'open %s failed\n' -- vprintf reaches printint only from its %d/%u/%x
   arms, which those three format strings refute. STAGE 5 adds [runcmd] and
   [fork1] -- the command TREE walk -- with the six further usys.S stubs
   they and the [cd] builtin issue: fork, exec, pipe, wait, chdir and dup.
   [runcmd]'s whole range is catalogued, the two fprintf-and-die tails
   included. SH LANE STAGES 1-2: the ELF entry, main's console preamble,
   and the COMMAND LOOP down to the blank-line test. [start] calls [main];
   main's first act is the loop that opens 'console' until it owns fd 3,
   then it closes it and falls into the command loop, whose head reads a
   line with [getcmd] -- write(2,'$ ',2), memset(buf,0,100), gets(buf,100)
   -- and skips leading blanks. open, close, exit and write take the QUIET
   row of the syscall memory table (UsysMemOk.usys_mem_ok); [read], which
   [gets] issues one byte at a time, takes the WINDOW row. The whole of
   [main] is catalogued, not just what is walked: the pc set is per
   function, and main's remaining arms -- the [cd] builtin at 0x96a and the
   fork/parse/run body at 0x908 -- are later stages over the same facts.

   Every AST below was READ OFF the model -- [vm_compute] of the decoder at
   the U-mode reference state [dstateU] (base) / [decode_c_pure] under the
   misa.C gate (compressed) -- never guessed. In particular every
   jal/branch immediate is the decoder's POSITIVE residue, and a COMPRESSED
   branch or jump immediate counts HALFwords. The compressed words decode
   to the raw C_* constructors -- the expansion into ITYPE/STORE/...
   happens in [execute], not here.
 *)
